module fuel_calculator(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [9:0] m,\n    input [9:0] a_i_0, a_i_1, a_i_2, a_i_3, a_i_4, a_i_5, a_i_6, a_i_7,\n    input [9:0] b_i_0, b_i_1, b_i_2, b_i_3, b_i_4, b_i_5, b_i_6, b_i_7,\n    output reg [63:0] fuel,\n    output reg done,\n    output reg impossible\n);\n    // State declarations\n    localparam [3:0]\n        IDLE       = 4'd0,\n        CHECK      = 4'd1,\n        COMPUTE_A  = 4'd2,\n        WAIT_DIV_A = 4'd3,\n        MULTIPLY_A = 4'd4,\n        COMPUTE_B  = 4'd5,\n        WAIT_DIV_B = 4'd6,\n        MULTIPLY_B = 4'd7,\n        FINAL_SUB  = 4'd8,\n        DONE_STATE = 4'd9;\n\n    reg [3:0] state, next_state;\n    reg [2:0] current_planet;\n    reg [63:0] product_reg;\n    reg [63:0] div_quotient;\n    reg start_div;\n    wire div_done;\n    reg [63:0] term;\n    reg [9:0] ai_current, bi_current;\n    reg any_invalid;\n    wire [63:0] m_fixed = { {22'd0}, m, 32'd0 };\n\n    // Division module instance\n    fixed_point_divider div (\n        .clk(clk),\n        .rst_n(rst_n),\n        .start(start_div),\n        .dividend({ {22'd0}, ai_current, 32'd0 }),\n        .divisor(ai_current - 1'd1),\n        .quotient(div_quotient),\n        .done(div_done)\n    );\n\n    // Combinational logic for input selection\n    always @(*) begin\n        case(current_planet)\n            3'd0: ai_current = a_i_0;\n            3'd1: ai_current = a_i_1;\n            3'd2: ai_current = a_i_2;\n            3'd3: ai_current = a_i_3;\n            3'd4: ai_current = a_i_4;\n            3'd5: ai_current = a_i_5;\n            3'd6: ai_current = a_i_6;\n            3'd7: ai_current = a_i_7;\n            default: ai_current = 10'd0;\n        endcase\n        case(current_planet)\n            3'd0: bi_current = b_i_0;\n            3'd1: bi_current = b_i_1;\n            3'd2: bi_current = b_i_2;\n            3'd3: bi_current = b_i_3;\n            3'd4: bi_current = b_i_4;\n            3'd5: bi_current = b_i_5;\n            3'd6: bi_current = b_i_6;\n            3'd7: bi_current = b_i_7;\n            default: bi_current = 10'd0;\n        endcase\n    end\n\n    // Invalid input check\n    always @(*) begin\n        any_invalid = 1'b0;\n        if (n >= 4'd1 && ((a_i_0 <= 10'd1) || (b_i_0 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd2 && ((a_i_1 <= 10'd1) || (b_i_1 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd3 && ((a_i_2 <= 10'd1) || (b_i_2 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd4 && ((a_i_3 <= 10'd1) || (b_i_3 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd5 && ((a_i_4 <= 10'd1) || (b_i_4 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd6 && ((a_i_5 <= 10'd1) || (b_i_5 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd7 && ((a_i_6 <= 10'd1) || (b_i_6 <= 10'd1))) any_invalid = 1'b1;\n        if (n >= 4'd8 && ((a_i_7 <= 10'd1) || (b_i_7 <= 10'd1))) any_invalid = 1'b1;\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            product_reg <= 64'd0;\n            term <= 64'd0;\n            current_planet <= 3'd0;\n            fuel <= 64'd0;\n            start_div <= 1'b0;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    if (start) begin\n                        product_reg <= m_fixed;\n                        state <= CHECK;\n                    end\n                end\n\n                CHECK: begin\n                    if (any_invalid) begin\n                        impossible <= 1'b1;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        current_planet <= 3'd0;\n                        state <= COMPUTE_A;\n                    end\n                end\n\n                COMPUTE_A: begin\n                    start_div <= 1'b1;\n                    term <= 64'd0;\n                    state <= WAIT_DIV_A;\n                end\n\n                WAIT_DIV_A: begin\n                    start_div <= 1'b0;\n                    if (div_done) begin\n                        term <= div_quotient;\n                        state <= MULTIPLY_A;\n                    end\n                end\n\n                MULTIPLY_A: begin\n                    product_reg <= (product_reg * term) >> 32;\n                    if (current_planet == n - 1) begin\n                        current_planet <= 3'd0;\n                        state <= COMPUTE_B;\n                    end else begin\n                        current_planet <= current_planet + 1;\n                        state <= COMPUTE_A;\n                    end\n                end\n\n                COMPUTE_B: begin\n                    start_div <= 1'b1;\n                    ai_current <= bi_current;  // Reuse divider for b_i terms\n                    state <= WAIT_DIV_B;\n                end\n\n                WAIT_DIV_B: begin\n                    start_div <= 1'b0;\n                    if (div_done) begin\n                        term <= div_quotient;\n                        state <= MULTIPLY_B;\n                    end\n                end\n\n                MULTIPLY_B: begin\n                    product_reg <= (product_reg * term) >> 32;\n                    if (current_planet == n - 1) begin\n                        state <= FINAL_SUB;\n                    end else begin\n                        current_planet <= current_planet + 1;\n                        state <= COMPUTE_B;\n                    end\n                end\n\n                FINAL_SUB: begin\n                    fuel <= product_reg - m_fixed;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule\n\nmodule fixed_point_divider #(\n    parameter WIDTH = 64\n)(\n    input clk,\n    input rst_n,\n    input start,\n    input [WIDTH-1:0] dividend,\n    input [9:0] divisor,\n    output reg [WIDTH-1:0] quotient,\n    output reg done\n);\n    reg [WIDTH-1:0] remainder;\n    reg [WIDTH-1:0] shifted_dividend;\n    reg [6:0] shift_count;\n    reg busy;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            quotient <= 0;\n            done <= 0;\n            shift_count <= 7'd0;\n            busy <= 0;\n            remainder <= 0;\n            shifted_dividend <= 0;\n        end else begin\n            if (start && !busy) begin\n                shifted_dividend <= dividend;\n                remainder <= 0;\n                shift_count <= 7'd0;\n                busy <= 1;\n                done <= 0;\n            end else if (busy) begin\n                if (shift_count < WIDTH) begin\n                    // Restoring division step\n                    remainder = {remainder[WIDTH-2:0], shifted_dividend[WIDTH-1]} << 1;\n                    if (remainder >= {52'd0, divisor}) begin\n                        remainder = remainder - {52'd0, divisor};\n                        shifted_dividend = {shifted_dividend[WIDTH-2:0], 1'b1};\n                    end else begin\n                        shifted_dividend = {shifted_dividend[WIDTH-2:0], 1'b0};\n                    end\n                    shift_count <= shift_count + 1;\n                end else begin\n                    quotient <= shifted_dividend;\n                    done <= 1;\n                    busy <= 0;\n                end\n            end else begin\n                done <= 0;\n            end\n        end\n    end\nendmodule